170: } iconv_ccs_convtable_16bit;	/* 16-bit charset to Unicode;
171: 				 * Unicode to any charset */
172: 
173: /*
174:  * abstract coded character set conversion table
175:  */
176: typedef union {
177: 	iconv_ccs_convtable_7bit	_7bit;
178: 	iconv_ccs_convtable_8bit	_8bit;
179: 	iconv_ccs_convtable_14bit	_14bit;
180: 	iconv_ccs_convtable_16bit	_16bit;
181: } iconv_ccs_convtable;
