200: /*
201:  * inline functions for use in charset conversion modules
202:  */
203: static APR_INLINE ucs2_t
204: iconv_ccs_convert_7bit(const iconv_ccs_convtable *table, ucs2_t ch)
205: {
206: 	return ch & 0x80 ? UCS_CHAR_INVALID : table->_7bit.data[ch];
207: }
208: 
209: static APR_INLINE ucs2_t
210: iconv_ccs_convert_8bit(const iconv_ccs_convtable *table, ucs2_t ch)
211: {
212: 	return table->_8bit.data[ch];
213: }
214: 
215: static APR_INLINE ucs2_t
216: iconv_ccs_convert_14bit(const iconv_ccs_convtable *table, ucs2_t ch)
217: {
218: 	const iconv_ccs_convtable_7bit *sub_table;
219: 
220: 	sub_table =  ch & 0x8080 ? NULL : table->_14bit.data[ch >> 8];
221: 	return sub_table ? sub_table->data[ch & 0x7F] : UCS_CHAR_INVALID;
222: }
223: 
224: static APR_INLINE ucs2_t
225: iconv_ccs_convert_16bit(const iconv_ccs_convtable *table, ucs2_t ch)
226: {
227: 	const iconv_ccs_convtable_8bit *sub_table;
228: 
229: 	sub_table = table->_16bit.data[ch >> 8];
230: 	return sub_table ? sub_table->data[ch & 0xFF] : UCS_CHAR_INVALID;
231: }
